SELECT rentabilidad_1.poblacióndistribuidorgvf/gvi AS poblacióndistribuidorgvf/gvi,   ((CAST((CAST(SUM(rentabilidad_1.in) AS double precision) / NULLIF(SUM(rentabilidad_1.cf),0)) AS double precision) * CAST(cast('0.46999999999999997' as double precision) AS double precision)) - (CAST((SUM(rentabilidad_1.totalventa) + SUM(rentabilidad_1.totalreparto)) AS double precision) / NULLIF(SUM(rentabilidad_1.cf),0))) AS usr:calculation_2160818191446896:ok FROM rentabilidad_1 WHERE ((rentabilidad_1.sedeforaneosintec = 'Foraneo') AND (rentabilidad_1.zona = 'NR')) GROUP BY rentabilidad_1.poblacióndistribuidorgvf/gvi;
